+                        let result = filter.contains(&input, false)?;
+                        assert_eq!(result.len(), 8192);
+                        assert_eq!(result.null_count(), nulls);
+                        assert_eq!(
+                            result.true_count(),
+                            if vectorized { 8192 - nulls } else { 0 }
+                        );
+                        checks += 1;
+                    }
+                }
+            }};
+        }
