+
+pub(super) fn short_float_filter<T, F>(
+    values: &PrimitiveArray<T>,
+    fallback: F,
+) -> Arc<dyn StaticFilter + Send + Sync>
+where
+    T: ArrowPrimitiveType,
+    F: StaticFilter + Send + Sync + 'static,
+{
+    if (1..=3).contains(&values.len()) {
+        Arc::new(ShortFloatFilter::<T, F> {
+            // A short slice must not retain a large backing allocation.
+            values: values.iter().collect(),
+            fallback,
+        })
+    } else {
+        Arc::new(fallback)
+    }
+}
+
+struct ShortFloatFilter<T: ArrowPrimitiveType, F> {
+    values: PrimitiveArray<T>,
+    fallback: F,
+}
+
+impl<T: ArrowPrimitiveType, F: StaticFilter> StaticFilter for ShortFloatFilter<T, F> {
+    fn null_count(&self) -> usize {
+        self.fallback.null_count()
+    }
+
+    fn contains(&self, v: &dyn Array, negated: bool) -> Result<BooleanArray> {
+        // ponytail: retain hashing below the measured 8192-row cutoff;
+        // lower it only after measuring comparison setup costs.
+        if v.len() >= 8192
+            && let Some(v) = v.as_primitive_opt::<T>()
+        {
+            let compare = |i| eq(v, &Scalar::new(self.values.slice(i, 1)));
+            let mut found = compare(0)?;
+            for i in 1..self.values.len() {
+                if found.null_count() == 0 && !found.has_false() {
+                    break;
+                }
+                found = or_kleene(&found, &compare(i)?)?;
+            }
+            return Ok(if negated { not(&found)? } else { found });
+        }
+        self.fallback.contains(v, negated)
+    }
+}
+
