+            Err(exec_datafusion_err!("hash fallback"))
+        }
+    }
+
+    #[test]
+    fn short_float_filter_keeps_hash_fallbacks() -> Result<()> {
+        fn check<T: ArrowPrimitiveType>(large: PrimitiveArray<T>) -> Result<usize> {
+            let mut checks = 0;
+            for length in 0..=4 {
+                let references = large.values().inner().strong_count();
