use std::{fs, hint::black_box, sync::Arc, time::Instant};
use arrow::{array::*, datatypes::*, record_batch::RecordBatch};
use datafusion_common::{Result, ScalarValue};
use datafusion_physical_expr::{PhysicalExpr, expressions::{col, lit, InListExpr}};
use serde_json::json;

fn main() -> Result<()> {
    let output = std::env::args().nth(1).unwrap();
    let mut results = vec![];
    for data_type in [DataType::Float32, DataType::Float64, DataType::Int32, DataType::Int64, DataType::Utf8] {
        for rows in [1, 8, 32, 8192] {
            for length in [1, 3, 4] {
                for pattern in ["mixed", "nullable"] {
                  for kind in ["array", "scalar"] {
                    let id = format!("{data_type:?}/{rows}/{length}/{pattern}/{kind}");
                    if std::env::args().nth(2).is_some_and(|selected| selected != id) { continue; }
                    let values = (0..rows).map(|i| {
                        if pattern == "nullable" && i % 3 == 0 { None }
                        else { Some(if pattern == "matched" { 1.0 } else { (i % 97) as f64 }) }
                    });
                    let array: ArrayRef = match data_type {
                        DataType::Float32 => Arc::new(Float32Array::from_iter(values.map(|v| v.map(|x| x as f32)))),
                        DataType::Float64 => Arc::new(Float64Array::from_iter(values)),
                        DataType::Int32 => Arc::new(Int32Array::from_iter(values.map(|v| v.map(|x| x as i32)))),
                        DataType::Int64 => Arc::new(Int64Array::from_iter(values.map(|v| v.map(|x| x as i64)))),
                        DataType::Utf8 => Arc::new(StringArray::from_iter(values.map(|v| v.map(|x| format!("value{x}"))))),
                        _ => unreachable!(),
                    };
                    let schema = Arc::new(Schema::new(vec![Field::new("a", data_type.clone(), true)]));
                    let batch = RecordBatch::try_new(schema.clone(), vec![array])?;
                    let list = (1..=length).map(|i| {
                        let v = if pattern == "nullable" && i == length { None } else { Some(i as f64) };
                        lit(match data_type {
                            DataType::Float32 => ScalarValue::Float32(v.map(|x| x as f32)),
                            DataType::Float64 => ScalarValue::Float64(v),
                            DataType::Int32 => ScalarValue::Int32(v.map(|x| x as i32)),
                            DataType::Int64 => ScalarValue::Int64(v.map(|x| x as i64)),
                            DataType::Utf8 => ScalarValue::Utf8(v.map(|x| format!("value{x}"))),
                            _ => unreachable!(),
                        })
                    }).collect();
                    let input = if kind == "scalar" { lit(ScalarValue::try_from_array(batch.column(0), 0)?) } else { col("a", &schema)? };
                    let expr = InListExpr::try_new(input, list, false, &schema)?;
                    let check = expr.evaluate(&batch)?.into_array(rows)?;
                    let check = as_boolean_array(&check);
                    let repetitions = (2_000_000 / rows).clamp(8, 20_000);
                    let mut samples_ns = vec![];
                    for sample in 0..11 {
                        let started = Instant::now();
                        for _ in 0..repetitions {
                            black_box(expr.evaluate(black_box(&batch))?);
                        }
                        if sample >= 2 {
                            samples_ns.push(started.elapsed().as_nanos() as f64 / repetitions as f64);
                        }
                    }
                    results.push(json!({
                        "id": id, "kind": kind,
                        "rows": rows, "list_length": length, "pattern": pattern,
                        "true_count": check.true_count(), "null_count": check.null_count(),
                        "repetitions": repetitions, "samples_ns": samples_ns,
                    }));
                  }
                }
            }
        }
    }
    fs::write(output, serde_json::to_vec_pretty(&results).unwrap())?;
    Ok(())
}

